input.command:
$files = @('ar','cn','de','el','es','he','in','it','jp','ru'); $keys = @{
  'CAL_OPEN' = 'Set North'
  'CAL_MODAL_TITLE' = 'North calibration'
  'CAL_MOUSE_CONFIRM' = 'Confirm North'
  'CAL_MOUSE_HINT_BAR' = 'Place N on the dial, then confirm'
}
foreach ($lang in $files) {
  $path = "c:\Dev\PATTOOL2\PatTool_Front-End\src\assets\i18n\$lang.json"
  $text = [IO.File]::ReadAllText($path)
  if ($text -notmatch '"CAL_OPEN"') {
    $text = $text -replace '("CAL_NEEDED":\s*"[^"]*",\s*)', "`$1`n    `"CAL_OPEN`": `"$($keys.CAL_OPEN)`",`n    `"CAL_MODAL_TITLE`": `"$($keys.CAL_MODAL_TITLE)`","
  }
  $text = $text -replace '"CAL_MOUSE_STEP3":\s*"[^"]*"', '"CAL_MOUSE_STEP3": "Then tap \"Confirm North\" to save."'
  if ($text -notmatch '"CAL_MOUSE_CONFIRM"') {
    $text = $text -replace '("CAL_MOUSE_DRAGGING":\s*"[^"]*",\s*)', "`$1`n    `"CAL_MOUSE_CONFIRM`": `"$($keys.CAL_MOUSE_CONFIRM)`",`n    `"CAL_MOUSE_HINT_BAR`": `"$($keys.CAL_MOUSE_HINT_BAR)`","
  }
  [IO.File]::WriteAllText($path, $text)
  Write-Output "updated $lang"
}
